import{_ as s,H as r,f as l,i as a}from"./chunks/framework.BH2BK_3i.js";const v=JSON.parse('{"title":"思维构建 | 如何在新赛道下进阶Serverless能力？","description":"","frontmatter":{},"headers":[{"level":2,"title":"新赛道：Serverless 的具象化表达","slug":"新赛道-serverless-的具象化表达","link":"#新赛道-serverless-的具象化表达","children":[]},{"level":2,"title":"发展历程：从单一到多元","slug":"发展历程-从单一到多元","link":"#发展历程-从单一到多元","children":[{"level":3,"title":"雏形阶段","slug":"雏形阶段","link":"#雏形阶段","children":[]},{"level":3,"title":"发展阶段","slug":"发展阶段","link":"#发展阶段","children":[]},{"level":3,"title":"成熟阶段","slug":"成熟阶段","link":"#成熟阶段","children":[]}]},{"level":2,"title":"切入点：升级打怪的进阶之路","slug":"切入点-升级打怪的进阶之路","link":"#切入点-升级打怪的进阶之路","children":[]},{"level":2,"title":"写在最后","slug":"写在最后","link":"#写在最后","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Serverless进阶实战课/思维构建｜如何在新赛道下进阶Serverless能力？.md","filePath":"Serverless进阶实战课/思维构建｜如何在新赛道下进阶Serverless能力？.md","lastUpdated":1795535054000}'),t={name:"Serverless进阶实战课/思维构建｜如何在新赛道下进阶Serverless能力？.md"};function i(n,e,p,E,o,S){return r(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="思维构建-如何在新赛道下进阶serverless能力" tabindex="-1">思维构建 | 如何在新赛道下进阶Serverless能力？ <a class="header-anchor" href="#思维构建-如何在新赛道下进阶serverless能力" aria-label="Permalink to &quot;思维构建 | 如何在新赛道下进阶Serverless能力？&quot;">​</a></h1><p>你好，我是静远。</p><p>Serverless 发展到现今，大部分的技术人已经对 Serverless 将引领云计算的下一个十年达成了共识。作为一名技术研发人员，“Serverless”对你来说大概率并不陌生，甚至，你已经在不知不觉中用上了，但是，它的快速发展也让我们很难对它形成一个较为全面的认知。</p><p>那么这节课，我们就一起了解 Serverless 的前世今生，重构 Serverless 思维，并选择一个具象化的 Serverless 形态作为切入点，开启后续的学习。最后，我也会和你探讨后续学习“升级打怪”的各个阶段，让我们的进阶目标更加清晰。</p><h2 id="新赛道-serverless-的具象化表达" tabindex="-1">新赛道：Serverless 的具象化表达 <a class="header-anchor" href="#新赛道-serverless-的具象化表达" aria-label="Permalink to &quot;新赛道：Serverless 的具象化表达&quot;">​</a></h2><p>简单来说，Serverless 是一种架构设计的理念，它不是一个具体的编程框架、类库或者工具。随着大家对于 Serverless 理解的深入，用词也越来越精准、具象。从之前“无服务器”的直译到目前“服务器无感知”的理解，是各界对 Serverless 这几年发展和使用的一个跨度的体现。</p><p>我们从头看一遍这个新赛道的发展历程。用 Martin Fowler 的观点来说，Serverless 是 FaaS和 BaaS 的组合，这个简单明了的定义，奠定了 Serverless 组成结构的基础。</p><p>CNCF 在认定这个理念的同时，也在它的白皮书 V1.0 中对 Serverless 架构的定义有了进一步地完善描述，它指出：Serverless Computing 是构建和运行不需要服务器管理的应用程序。它描述了一种更细粒度的部署模型，将一个或多个功能的应用程序打包上传到 Serverless 平台，然后根据实际的需求，执行、扩展和计费。</p><p>我们发现，这个描述从执行路径和更细的角度进行了具象化的表述。</p><p>在 2022 年 7 月的云原生产业大会上，信通院发布的最新的云计算白皮书针对 Serverless 的描述中提到，“通过多种服务器无感知技术，将基础设施抽象成各种开箱即用的服务，以 API 接口的方式提供给用户按需调用，真正做到按需伸缩、按使用量收费”，又进一步从业务和基础设施服务的协作角度，凸显了 Serverless 的特性。</p><p>我沿用信通院白皮书的话来体现这种思想，也希望我们能够达成一个共识：“Serverless 是能够实现业务和基础设施分离，提升用户业务创新能力的理念”。</p><h2 id="发展历程-从单一到多元" tabindex="-1">发展历程：从单一到多元 <a class="header-anchor" href="#发展历程-从单一到多元" aria-label="Permalink to &quot;发展历程：从单一到多元&quot;">​</a></h2><p>除了理念上的落地，我们再说一下 Serverless 的技术和应用场景向多元化发展的历程。以史为镜可以知兴替，理解 Serverless 多元化的历程，才能更完整地构建你的 Serverless 思维。</p><h3 id="雏形阶段" tabindex="-1">雏形阶段 <a class="header-anchor" href="#雏形阶段" aria-label="Permalink to &quot;雏形阶段&quot;">​</a></h3><p>国外可以追溯到 2006 年，Fotango 公司推出的 PaaS 平台 Zimki，提出了按需使用、按量付费的概念，从那时 Serverless 的核心特征就已见雏形了。到 2012 年，基础设施服务提供商Iron.io 的副总裁 Ken 在《Why The Future of Software and Apps is Serverless》中首次提到“Serverless”这个词，它正式走进历史的舞台。我们可以认为，这一阶段就是 Serverless 发展的“雏形阶段”。</p><h3 id="发展阶段" tabindex="-1">发展阶段 <a class="header-anchor" href="#发展阶段" aria-label="Permalink to &quot;发展阶段&quot;">​</a></h3><p>AWS 于 2014 年发布第一款函数计算产品 —— Lambda 预览版，并于 2015 年正式商用，使用量随后一路飙升，随后，IMB、Google、Micosoft 也于 2016 年相继发布 FaaS 产品，开源项目也同时出现，这里包括比较知名的 OpenWisk、Fission、Kubeless、OpenFaaS 等。</p><p>到 2017 年，国内头部的四朵云（阿里、腾讯、华为、百度）也相继发布了 FaaS 产品。同年，Azure 发布了首个 Serverless 容器 ACI，AWS 发布 Serverless 容器服务 Fargate。</p><p>可以说，Serverless 的领域内，大家追逐和创新的劲头彰显得非常明显。这一段时间出现了函数计算、容器实例、容器服务等产品。从下面的 Google Trends 也可以看出，人们对于无服务器和 Lambda 的关注度是不断提升的。我们可以认为，这是 Serverless 的发展阶段。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/1.png" alt=""></a></p><h3 id="成熟阶段" tabindex="-1">成熟阶段 <a class="header-anchor" href="#成熟阶段" aria-label="Permalink to &quot;成熟阶段&quot;">​</a></h3><p>2018 年，华为云发布了 Serverless 容器服务 CCI，阿里云发布面向应用的 Serverless 托管服务 SAE。在开源方面，Knative 发布，并于 2022 年 3 月成为 CNCF 孵化项目。</p><p>时隔一年，阿里云、Google、腾讯云先后发布了 Serverless 容器服务，截止到去年，各大公司又相继推出了 Serverless 应用托管服务，旨在进一步为用户提供全托管、免运维和高弹性的服务能力，一方面可以解决存量的微服务应用上云，另一方面可以高效地集成和持续交付等。这一期间直接把 Serverless 推到了一个相对成熟的阶段。</p><p>可以说，随着 Serverelss 技术和价值的体现，各大公司都在你追我赶地发展，国内厂商虽然是后来者，但追赶势头迅猛，目前的竞争力也能够和国外大公司相互比肩。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/2.png" alt=""></a></p><p>从发展历程中，我们也可以看出，以函数为起点，Serverless 的技术和产品逐步趋于多元化。多种形态相互补充，为解决更复杂、更多样化的业务场景提供支撑，我们通常会把场景分为三类：</p><ul><li><p>函数计算（FaaS）：面向函数，用户只需关注函数层级的代码，用于解决轻量型、无状态、有时效的任务；</p></li><li><p>Serverless 应用托管：面向应用，用户只需要更关注应用本身，与微服务结合，它融合应用治理、可观测，降低了新应用的构建成本、老应用的适配改造成本；</p></li><li><p>Serverelss 容器服务：面向容器，在不改变当前 Kubernetes 的前提下，由于不再需要关注节点，大大提升了前期资源的准备过程，降低了维护成本，使得应用的全生命周期管理更高效。</p></li></ul><p>随着 Serverless 的内涵持续外延，计算的 Serverless 化要求 BaaS 服务也具备与之配套的托管能力和极致弹性，全链路完整支撑真正 Serverless 化的应用构建。</p><p>那么，我们讨论的“Serverless”已经不再是原来狭义上的 Serverless——函数即服务了。广义上，Serverless 的特性应该同时体现在 Serverless DB、Serverless 消息队列、工作流、工具链等等方面。如今，在资源层的 Serverless 上，各大公司也相继研究发布了各种产品，如数据库层面的Amazon Aurora Serverless、PostgreSQL for Serverless、PolarDBServerless等。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/3.png" alt=""></a></p><ul><li>资料来源于信通院</li></ul><p>除了定义内涵在不断的丰富，Serverless 的应用场景也在迅猛扩展。它不再局限在小程序、定时任务、简单事件的触发、批量场景的处理了，基于 AI 的集成、大规模数据的处理、IOT 数据处理、微服务托管上云等领域都随处可见 Serverless 的身影。</p><p>我再附上一张信通院标准书中的 Serverless 解决方案图，帮助你更好地梳理 Serverless 的知识要点，在课程的开始，构建起 Serverless 的模型和思维。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/4.png" alt=""></a></p><ul><li>资料来源于信通院标准书</li></ul><h2 id="切入点-升级打怪的进阶之路" tabindex="-1">切入点：升级打怪的进阶之路 <a class="header-anchor" href="#切入点-升级打怪的进阶之路" aria-label="Permalink to &quot;切入点：升级打怪的进阶之路&quot;">​</a></h2><p>了解了 Serverless 的发展、价值和架构模式，具备了 Serverless 的意识形态之后，相信你已经对 Serverless 这个新赛道脱离了之前的印象了。</p><p>Serverless 的多而杂，一方面让我们更期待它未来的发展，但另一方面，也的确提升了我们学习的难度。那我们要怎么切入这个新赛道，紧跟云计算下一个十年的发展趋势呢？</p><p>正如开篇词中所说，我不希望你面面俱到地学习很多具象化的技术，那样只会“杂而不纯，博而不精”。我建议你从 FaaS 形态的 Serverless 入手，为什么要给出这个建议呢？</p><p>首先，Serverless 如同太极，确实讲究“用意不用力”，但学习“太极”也讲究前期的武功招式，只是练就到最后，应该忘形存神。那么选择一个具象化的产品来学习新赛道下的 Serverless是非常有必要的。</p><p>其次，FaaS 作为 Serverless 意识形态的“元老”级别产品，从 AWS Lambda 的发布，到众多厂商的跟进，已经发展 8 个年头了。自定义运行时、自定义镜像、编排、应用中心等也都是基于 FaaS 打造和延伸的功能。因此，FaaS 形态的 Serverless 是你入手的不二选择。</p><p>那么，我们如何学习 Serverelss FaaS 这一套“拳法”呢，我列了这一个简单示意图，下面我依次来跟你讲一下如何达到每一个层级。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/5.png" alt=""></a></p><ul><li>Hello World</li></ul><p>这个层面最简单，你只要具备任意一个云厂商的账号，创建一个函数运行起来，就算是迈出了Serverless 学习的第一步。</p><p>在学习的过程中也不需要任何的成本，云厂商一般都有免费的额度，不用担心费用问题，直接上手练习、使用就好。</p><ul><li>能用</li></ul><p>要想达到这一层，你需要经常去云厂商的网站浏览，学习手册，再找一些公众号等博文资料了解。</p><p>完成这一次进阶的你，一定已经基本了解了一个 Serverless 的平台都有哪些功能，也能够简单的实操，可以做一般的售前解决方案了。不过，还并不具备很强的开发能力。</p><ul><li>会开发简单业务</li></ul><p>这一层开始，就是针对开发层面的学习了。</p><p>一方面，你需要掌握一门比较流行的编程语言，比如 Python、Golang 等，另一方面，你还需要持续关注业界公布的各种案例和云厂商的手册，跟着来改造你的代码。做到这两方面，这一层进阶也就完成了。</p><ul><li>会开发复杂业务</li></ul><p>达到这一层次的开发同学，必须将函数计算的各种技能融会贯通，知道什么情况用什么策略更好，当然，在社区和云厂商的答疑上也会有一些分享，可以持续关注。</p><ul><li>能沉淀公共能力</li></ul><p>这个层级属于业务开发的最高级。简单来说，你在开发自己业务代码的时候，能够沉淀出相关的类库、层供你和其他同学或者平台上的其他开发者使用的能力，这是抽象能力的体现。</p><p>在达成进阶之前，你应该就已经具备能撰写类库的能力，且学习过相关的抽象思维、设计相关的知识，并有这种意识去执行。</p><ul><li>计量计费</li></ul><p>作为一个平台，计量计费是少不了的。这个层级，也可以说是希望具备平台开发能力的同学需要达到的初级阶段。</p><p>你需要提前具备 Kubernetes、Docker、架构设计、中间件的基础知识，在此基础上，你还需要系统性地吸收 Serverless 的一线实战案例和经验，才有可能避免踩坑。</p><ul><li>平台可迁移</li></ul><p>这个层级属于平台开发的王者阶段。你开发的平台不仅可以在你的云上使用，还可以帮助私有化企业部署，甚至可以组件化的方式输出。</p><p>想要完成这个层级的进阶，我的建议是加入一个云原生的 Serverless 团队，在里面打磨一万小时以上，扎扎实实地搞清楚每个点，假以时日，你才能在这个领域崭露头角。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>到这里，你应该已经对 Serverless 有了不一样的理解。</p><p>Serverless 是能够实现业务和基础设施分离，提升用户业务创新能力的理念。我给你整理了一个图，突出几个核心特征组成了它的形式：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E6%2580%259D%25E7%25BB%25B4%25E6%259E%2584%25E5%25BB%25BA/6.png" alt=""></a></p><p>其中，从物理组成上，FaaS 和 BaaS 组成了 Serverless 的基本构成，这就跟汽车由车身和车轮构成一个道理；而通过开箱即用、API 形式调用等动作描述了 Serverless 的运作形态，这就跟汽车需要发动引擎、脚踩刹车的使用逻辑类似；最后，按需调用、按量收费的几个核心特征体现了 Serverless 的“最大卖点”，好比似汽车的自动驾驶、自动泊车功能一样。</p><p>这样了解下来，你是不是对 Serverless 的理解更亲切了呢？</p><p>Serverless 发展到今天形成了以函数计算、弹性应用、容器服务为核心的产品形态，并逐步泛化和外延，使得其形态趋于多元化，形成互补之力，能够满足更多的场景。</p><p>但是，Serverless 思维的建立一定不是一蹴而就的。在它未来发展的几年中，也一定会越来越泛化，它一定会继续融合更多的生态，更多的 Serverless 产品形态也将会不断涌现。我们要做的，就是“保持一颗拥抱变化的心”，扎根于 Serverless 的本质精髓，透过产品了解背后的技术原理和初衷。</p><p>在后面的课程中，我希望你不仅跟着学习文章中的理论知识，也能够随着课程中提到的实战去自己动手练习，积极地参与讨论和思考，通过“学习 - 实践 - 总结 - 表达”的过程去探索这门不断延伸的技术。</p><p>在这样的学习下，我相信你一定可以触类旁通，“随敌而变，随招而变”，达到真正的“用意不用力”。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你在步入 Serverless 领域的时候，有没有遇到什么困惑呢？欢迎分享出来，我们一起讨论解决。</p><p>感谢你的阅读，也欢迎你把这节课分享给更多的朋友一起阅读和交流。我们下一讲见。</p>',76)])])}const h=s(t,[["render",i]]);export{v as __pageData,h as default};
